// UAE Corporate Tax Calculator
function calculateUAECorporateTax(netProfitAED, revenueAED) {
  if (revenueAED <= 3000000) {
    return { taxDue: 0, status: 'Small Business Relief Eligible (0%)' };
  }
  if (netProfitAED <= 375000) return { taxDue: 0, status: '0% Baseline Threshold' };

  const taxablePortion = netProfitAED - 375000;
  const taxDue = taxablePortion * 0.09;
  return { taxDue, effectiveRate: (taxDue / netProfitAED) * 100 };
}

