// UAE End-of-Service Gratuity (EOSG) Calculation
function calculateEOSG(basicSalaryAED, yearsOfService) {
  let gratuity = 0;
  if (yearsOfService < 1) return 0;
  if (yearsOfService <= 5) {
    gratuity = (basicSalaryAED / 30) * 21 * yearsOfService;
  } else {
    const first5Years = (basicSalaryAED / 30) * 21 * 5;
    const extraYears = (basicSalaryAED / 30) * 30 * (yearsOfService - 5);
    gratuity = first5Years + extraYears;
  }
  // Max cap: 2 years total basic salary
  return Math.min(gratuity, basicSalaryAED * 24);
}
